//! Artifact-byte and GitHub-attestation verification for durable releases.
//!
//! A manifest is only a claim. This module verifies the actual on-disk bytes
//! and asks GitHub to validate the signing certificate against the policy
//! embedded in the immutable release intent before an executor can upload an
//! asset. It intentionally owns no upload side effect.

use std::{
    fs::{self, File},
    path::{Component, Path, PathBuf},
    time::Duration,
};

use callisto_model::{ArtifactManifestV1, CommandRunner, ReleaseIntentV1};

use crate::GraphError;

const ATTESTATION_TIMEOUT: Duration = Duration::from_secs(120);

/// A manifest whose exact local bytes and GitHub provenance have been checked.
///
/// The constructor is private: callers can obtain this capability only with
/// [`verify_artifact_manifest`]. It borrows the manifest so an executor cannot
/// silently substitute a different manifest after verification.
#[derive(Debug)]
pub struct VerifiedArtifactManifest<'a> {
    manifest: &'a ArtifactManifestV1,
}

impl<'a> VerifiedArtifactManifest<'a> {
    pub fn manifest(&self) -> &'a ArtifactManifestV1 {
        self.manifest
    }
}

/// Verifies every manifest entry against the exact artifact directory.
///
/// The artifact directory and every candidate are canonicalized, and symbolic
/// links are rejected, so a manifest asset name cannot escape the supplied
/// build-output directory. Each asset is streamed once for a bounded-memory
/// SHA-256 and size comparison. `gh attestation verify` then validates the
/// repository, workflow path and commit, source commit, and hosted-runner
/// policy declared by the immutable artifact slot.
pub fn verify_artifact_manifest<'a, R: CommandRunner>(
    intent: &ReleaseIntentV1,
    manifest: &'a ArtifactManifestV1,
    artifact_root: &Path,
    runner: &R,
) -> Result<VerifiedArtifactManifest<'a>, GraphE<truncated omitted_approx_tokens="968" />str) -> Result<Option<CommitSha>, VcsError>;

    /// Lists commits reachable from `HEAD`, down to (exclusive) `since_ref`
    /// when given, filtered to those that touch at least one of
    /// `pathspecs` (an empty slice disables filtering and returns every
    /// commit in the walk). Merge commits are always excluded, matching
    /// `git log --no-merges`.
    ///
    /// Unlike [`Self::resolve_commit`], a `since_ref` that's given but
    /// fails to resolve to a commit *is* an error: silently ignoring it and
    /// walking unbounded history instead of the caller's requested bound
    /// is a correctness bug (e.g. it can re-surface already-released
    /// commits into changelog/severity inference). `since_ref: None` is not
    /// this case -- it's a deliberate request for the full history and
    /// always succeeds.
    fn commits_since(&self, since_ref: Option<&str>, pathspecs: &[PathBuf]) -> Result<Vec<GitCommit>, VcsError>;

    /// Creates the tag `name` at `target_sha`: annotated with `message`
    /// when `Some`, lightweight when `None`. Fails if a ref of that name
    /// already exists.
    ///
    /// `sign` controls whether the ambient Git signing configuration is
    /// allowed to apply -- see [`TagSignPolicy`].
    ///
    /// Writes a git ref, so it requires an [`ApplyPermit`]; a dry run has
    /// none to give and therefore cannot call this at all.
    fn create_tag(
        &self,
        name: &str,
        target_sha: &CommitSha,
        message: Option<&str>,
        sign: TagSignPolicy,
        permit: &ApplyPermit,
    ) -> Result<(), VcsError>;

    /// Force-creates or -moves the floating tag `major_name` to point at
    /// `target_sha`, overwriting any existing ref of that name.
    ///
    /// Writes a git ref, so it requires an [`ApplyPermit`].
    fn create_floating_major(
        &self,
        major_name: &str,
        target_sha: &CommitSha,
        permit: &ApplyPermit,
    ) -> Result<(), VcsError>;

